package com.englishhero.practice;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import com.englishhero.identity.SessionPrincipal;
import com.englishhero.reading.*;
import com.englishhero.web.BusinessException;
import static com.englishhero.practice.PracticeDtos.*;
@Service @Transactional(isolation=Isolation.READ_COMMITTED)
public class PracticeImportService {
 private final PracticeAdminService admin;private final AdminArticleService articleAdmin;private final ArticleMapper articles;private final PracticeSetMapper sets;private final PracticeQuizMapper quizzes;private final PracticeAttemptMapper requests;private final PracticePublicationChecks checks;private final PracticeAudioService audio;
 public PracticeImportService(PracticeAdminService admin,AdminArticleService articleAdmin,ArticleMapper articles,PracticeSetMapper sets,PracticeQuizMapper quizzes,PracticeAttemptMapper requests,PracticePublicationChecks checks,PracticeAudioService audio){this.audio=audio;this.admin=admin;this.articleAdmin=articleAdmin;this.articles=articles;this.sets=sets;this.quizzes=quizzes;this.requests=requests;this.checks=checks;}
 private DraftInput valid(SessionPrincipal actor,ImportInput input){articleAdmin.requireAdmin(actor);if(input==null)throw BusinessException.invalid("json","请提供单组JSON");var d=PracticeDraftRules.normalize(input.draft());if(d.listening()!=null&&d.listening().audioAssetId()!=null)audio.requireOwnedAsset(actor,d.listening().audioAssetId());if("LISTENING".equals(d.readingType())&&!articles.practiceOnly(ArticleRules.id(d.articleId(),"articleId")))throw BusinessException.invalid("articleId","听力只能引用专项专用原文");var article=articleAdmin.preview(actor,d.articleId(),d.articleVersionId());var state=new DraftState(d.metadata(),Map.of(),null,d.readingType(),d.wordBank(),d.listening());var body=article.content().paragraphs().stream().map(p->p.sentences().stream().map(com.englishhero.reading.ArticleContent.Sentence::text).reduce((a,b)->a+"\n"+b).orElse("")).reduce((a,b)->a+"\n\n"+b).orElse("");var errors=new LinkedHashMap<String,String>();for(var c:checks.source(0,state,d.questions(),d.readingType(),body))errors.putIfAbsent(c.path(),c.message());for(var q:d.questions())for(var c:checks.question(q,d.readingType(),d.wordBank()))errors.putIfAbsent(c.path(),c.message());if(!errors.isEmpty())throw new BusinessException(400,"VALIDATION_ERROR","请检查导入内容",errors);return d;}
 public ImportValidation validate(SessionPrincipal actor,ImportInput input){articleAdmin.requireAdmin(actor);try{var d=valid(actor,input);return new ImportValidation(true,Map.of(),d.questions().size());}catch(BusinessException e){if(e.status==401||e.status==403)throw e;return new ImportValidation(false,e.fields.isEmpty()?Map.of("articleId",e.getMessage()):e.fields,0);}}
 public AdminSet importDraft(SessionPrincipal actor,ImportInput input){var d=valid(actor,input);PracticeAttemptService.requestId(input.requestId());long aid=ArticleRules.id(d.articleId(),"articleId");articles.article(aid,true);var existing=sets.forArticle(aid);if(existing!=null){quizzes.get(existing.quizId(),true);sets.get(existing.id(),true);}requests.lockUser(actor.userId());String hash=checks.hash(List.of("IMPORT",d));var previous=requests.request(actor.userId(),input.requestId());if(previous!=null){PracticeAttemptService.checkRequest(previous,"IMPORT",hash);return admin.get(actor,""+previous.set());}if(existing!=null)throw new BusinessException(409,"PRACTICE_ALREADY_EXISTS","这篇文章已有题组，导入不会覆盖已有草稿",Map.of("existingSetId",""+existing.id()));var result=admin.create(actor,d);requests.remember(actor.userId(),input.requestId(),"IMPORT",hash,null,Long.parseLong(result.id()),result.lockVersion());return result;}
}
